package com.sumedha.commerce.user.entity; import com.sumedha.commerce.user.enums.AddressType; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="addresses") public class Address { @Id @Column(name="address_id") private UUID id; @Column(name="profile_id",nullable=false) private UUID profileId; @Enumerated(EnumType.STRING) @Column(name="address_type") private AddressType type; private String recipientName,line1,line2,city,stateRegion,postalCode,countryCode,phone; @Column(name="is_default") private boolean defaultAddress; @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; protected Address(){} public Address(UUID p,AddressType t,String r,String l1,String l2,String c,String s,String pc,String cc,String ph,boolean d){id=UUID.randomUUID();profileId=p;update(t,r,l1,l2,c,s,pc,cc,ph,d);createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void touch(){updatedAt=Instant.now();} public UUID getId(){return id;} public UUID getProfileId(){return profileId;} public AddressType getType(){return type;} public String getRecipientName(){return recipientName;} public String getLine1(){return line1;} public String getLine2(){return line2;} public String getCity(){return city;} public String getStateRegion(){return stateRegion;} public String getPostalCode(){return postalCode;} public String getCountryCode(){return countryCode;} public String getPhone(){return phone;} public boolean isDefaultAddress(){return defaultAddress;} public void clearDefault(){defaultAddress=false;} public void update(AddressType t,String r,String l1,String l2,String c,String s,String pc,String cc,String ph,boolean d){type=t;recipientName=r;line1=l1;line2=l2;city=c;stateRegion=s;postalCode=pc;countryCode=cc;phone=ph;defaultAddress=d;} }
